<?php
namespace Modules\Academy\Services;
use Core\database\DB;
use Core\translation\TranslationService;
use Modules\System\Services\SiteAdminAccess;
use RuntimeException;

class AcademyClassroomService {
    private function tr(string $table,int $id,string $field): string { return TranslationService::manager()->get($table,$id,$field,'fa')?:''; }
    private function set(string $table,int $id,array $values,int $actor): void { foreach($values as $field=>$value)if(!TranslationService::manager()->set($table,$id,$field,(string)$value,'fa'))throw new RuntimeException('ذخیره ترجمه ناموفق بود.');DB::table('translations')->where('table_name',$table)->where('table_id',$id)->where('locale','fa')->update(['created_by'=>$actor,'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null]); }
    private function branches(int $actor,bool $admin): array {
        if($admin)return DB::table('academy_branches')->whereNull('deleted_at')->get();
        $user=DB::table('users')->where('user_id',$actor)->whereNull('deleted_at')->first();
        if(!$user)throw new RuntimeException('کاربر معتبر نیست.');
        if(($user['type']??'')==='branch')return DB::table('academy_branches')->where('user_id',$actor)->whereNull('deleted_at')->get();
        $academies=array_merge(
            DB::table('academies')->where('user_id',$actor)->whereNull('deleted_at')->get(),
            DB::table('academies')->where('created_by',$actor)->whereNull('deleted_at')->get()
        );
        $academyIds=array_values(array_unique(array_map(fn($academy)=>(int)$academy['academy_id'],$academies)));
        if(!$academyIds)throw new RuntimeException('آموزشگاه مرتبط یافت نشد.');
        return DB::table('academy_branches')->whereIn('academy_id',$academyIds)->whereNull('deleted_at')->get();
    }
    private function allowedBranch(int $actor,int $branchId,bool $admin): array { foreach($this->branches($actor,$admin) as $b)if((int)$b['branch_id']===$branchId)return $b;throw new RuntimeException('شعبه معتبر نیست.'); }
    public function bootstrap(int $actor,bool $admin): array { $branches=$this->branches($actor,$admin);$ids=array_map(fn($b)=>(int)$b['branch_id'],$branches);$types=DB::table('academy_branch_classroom_types')->whereNull('deleted_at')->get();$rooms=$ids?DB::table('academy_branch_classrooms')->whereIn('branch_id',$ids)->whereNull('deleted_at')->get():[];return ['branches'=>array_map(fn($b)=>['id'=>(int)$b['branch_id'],'name'=>$this->tr('academy_branches',(int)$b['branch_id'],'name')?:'شعبه '.$b['branch_id']],$branches),'types'=>array_map(fn($t)=>$this->type($t),$types),'classrooms'=>array_map(fn($r)=>$this->room($r),$rooms)]; }
    private function type(array $r): array {$id=(int)$r['classroom_type_id'];return ['id'=>$id,'name'=>$this->tr('academy_branch_classroom_types',$id,'title')?:$r['code'],'title'=>$this->tr('academy_branch_classroom_types',$id,'title')?:$r['code'],'summary'=>$this->tr('academy_branch_classroom_types',$id,'summary'),'description'=>$this->tr('academy_branch_classroom_types',$id,'description')];}
    private function room(array $r): array {$id=(int)$r['classroom_id'];$type=$r['type_id']?DB::table('academy_branch_classroom_types')->where('classroom_type_id',(int)$r['type_id'])->first():null;$assets=DB::table('academy_branch_classroom_assets')->where('classroom_id',$id)->whereNull('deleted_at')->get();$branch=DB::table('academy_branches')->where('branch_id',(int)$r['branch_id'])->first();return ['id'=>$id,'name'=>$this->tr('academy_branch_classrooms',$id,'title')?:'کلاس '.$id,'summary'=>$this->tr('academy_branch_classrooms',$id,'summary'),'description'=>$this->tr('academy_branch_classrooms',$id,'description'),'typeId'=>(int)($r['type_id']?:0),'type'=>$type?($this->tr('academy_branch_classroom_types',(int)$type['classroom_type_id'],'title')?:$type['code']):'—','typeLabel'=>$type?($this->tr('academy_branch_classroom_types',(int)$type['classroom_type_id'],'title')?:$type['code']):'—','branchId'=>(int)$r['branch_id'],'branchName'=>$branch?($this->tr('academy_branches',(int)$branch['branch_id'],'name')?:'شعبه '.$branch['branch_id']):'—','capacity'=>(int)$r['capacity'],'status'=>match($r['status']){'available'=>'فعال','maintenance'=>'تعمیر',default=>'غیرفعال'},'equipment'=>array_map(fn($a)=>['id'=>(int)$a['classroom_asset_id'],'name'=>$this->tr('academy_branch_classroom_assets',(int)$a['classroom_asset_id'],'title'),'qty'=>(int)$a['quantity']],$assets)];}
    public function saveRoom(int $actor,array $d,bool $admin,int $id=0): array {return transaction(function()use($actor,$d,$admin,$id){$branchId=(int)($d['branchId']??0);$this->allowedBranch($actor,$branchId,$admin);$typeId=(int)($d['typeId']??0);if(!DB::table('academy_branch_classroom_types')->where('classroom_type_id',$typeId)->whereNull('deleted_at')->first())throw new RuntimeException('نوع کلاس معتبر نیست.');$name=trim((string)($d['name']??''));if($name==='')throw new RuntimeException('نام کلاس الزامی است.');$values=['branch_id'=>$branchId,'type_id'=>$typeId,'capacity'=>max(1,(int)($d['capacity']??1)),'is_active'=>($d['status']??'فعال')==='فعال'?1:0,'status'=>match($d['status']??'فعال'){'فعال'=>'available','تعمیر'=>'maintenance',default=>'pending'},'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];if($id){$room=DB::table('academy_branch_classrooms')->where('classroom_id',$id)->whereNull('deleted_at')->first();if(!$room)throw new RuntimeException('کلاس یافت نشد.');$this->allowedBranch($actor,(int)$room['branch_id'],$admin);DB::table('academy_branch_classrooms')->where('classroom_id',$id)->update($values);}else $id=DB::table('academy_branch_classrooms')->insertGetId(['created_by'=>$actor]+$values);$this->set('academy_branch_classrooms',$id,['title'=>$name,'summary'=>trim((string)($d['summary']??'')),'description'=>trim((string)($d['description']??''))],$actor);$old=DB::table('academy_branch_classroom_assets')->where('classroom_id',$id)->get();$oldIds=array_map(fn($x)=>(int)$x['classroom_asset_id'],$old);if($oldIds){DB::table('translations')->where('table_name','academy_branch_classroom_assets')->whereIn('table_id',$oldIds)->delete();DB::table('academy_branch_classroom_assets')->whereIn('classroom_asset_id',$oldIds)->delete();}foreach(($d['equipment']??[])as $asset){$title=trim((string)($asset['name']??''));if($title==='')continue;$aid=DB::table('academy_branch_classroom_assets')->insertGetId(['classroom_id'=>$id,'quantity'=>max(1,(int)($asset['qty']??1)),'created_by'=>$actor,'updated_by'=>$actor]);$this->set('academy_branch_classroom_assets',$aid,['title'=>$title],$actor);}return $this->room(DB::table('academy_branch_classrooms')->where('classroom_id',$id)->first());});}
    public function deleteRoom(int $actor,int $id,bool $admin): void {$r=DB::table('academy_branch_classrooms')->where('classroom_id',$id)->whereNull('deleted_at')->first();if(!$r)throw new RuntimeException('کلاس یافت نشد.');$this->allowedBranch($actor,(int)$r['branch_id'],$admin);$now=date('Y-m-d H:i:s');DB::table('academy_branch_classrooms')->where('classroom_id',$id)->update(['deleted_at'=>$now,'deleted_by'=>$actor,'updated_by'=>$actor]);DB::table('academy_branch_classroom_assets')->where('classroom_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor,'updated_by'=>$actor]);}
    public function saveType(int $actor,array $d,int $id=0): array {$title=trim((string)($d['title']??''));$summary=trim((string)($d['summary']??''));$description=trim((string)($d['description']??''));if(!$title||!$summary||!$description)throw new RuntimeException('عنوان، خلاصه و شرح الزامی هستند.');return transaction(function()use($actor,$title,$summary,$description,$id){$values=['code'=>'custom-'.substr(sha1($title),0,12),'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];if($id){if(!DB::table('academy_branch_classroom_types')->where('classroom_type_id',$id)->whereNull('deleted_at')->first())throw new RuntimeException('نوع کلاس یافت نشد.');DB::table('academy_branch_classroom_types')->where('classroom_type_id',$id)->update($values);}else$id=DB::table('academy_branch_classroom_types')->insertGetId(['created_by'=>$actor]+$values);$this->set('academy_branch_classroom_types',$id,['title'=>$title,'summary'=>$summary,'description'=>$description],$actor);return $this->type(DB::table('academy_branch_classroom_types')->where('classroom_type_id',$id)->first());});}
    public function deleteType(int $actor,int $id): void {if(DB::table('academy_branch_classrooms')->where('type_id',$id)->whereNull('deleted_at')->count())throw new RuntimeException('این نوع توسط کلاس فعال استفاده می‌شود.');$now=date('Y-m-d H:i:s');DB::table('academy_branch_classroom_types')->where('classroom_type_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor,'updated_by'=>$actor]);DB::table('translations')->where('table_name','academy_branch_classroom_types')->where('table_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor,'updated_by'=>$actor]);}
    public function seedFixtures(): array {return transaction(function(){ $defs=[['عمومی','کلاس مناسب آموزش‌های عمومی و نظری.','فضایی استاندارد برای کلاس‌های نظری، گروهی و آموزش عمومی.'],['ساز تخصصی','کلاس مجهز برای آموزش انفرادی ساز.','فضای آکوستیک و مجهز برای آموزش تخصصی انواع ساز.'],['تمرین گروهی','فضای مناسب تمرین گروه‌ها.','کلاس بزرگ‌تر برای تمرین گروه‌نوازی و اجرای گروهی.'],['آواز و صداسازی','کلاس ویژه آموزش آواز.','فضایی مناسب تمرین آواز، تنفس و تکنیک‌های صداسازی.']];$typeIds=[];foreach($defs as $i=>$d){$code='seed-classroom-type-'.($i+1);$row=DB::table('academy_branch_classroom_types')->where('code',$code)->first();if($row){$tid=(int)$row['classroom_type_id'];DB::table('academy_branch_classroom_types')->where('classroom_type_id',$tid)->update(['deleted_at'=>null,'deleted_by'=>null]);}else$tid=DB::table('academy_branch_classroom_types')->insertGetId(['code'=>$code,'created_by'=>1,'updated_by'=>1]);$this->set('academy_branch_classroom_types',$tid,['title'=>$d[0],'summary'=>$d[1],'description'=>$d[2]],1);$typeIds[]=$tid;} $branches=DB::table('academy_branches')->whereNull('deleted_at')->get();$created=0;$assets=0;foreach($branches as $bi=>$b){$count=1+($bi%20);for($i=1;$i<=$count;$i++){$title='کلاس '.($i).' - '.($this->tr('academy_branches',(int)$b['branch_id'],'name')?:$b['branch_id']);$existing=null;foreach(DB::table('translations')->where('table_name','academy_branch_classrooms')->where('field','title')->where('locale','fa')->where('value',$title)->get() as $t){$candidate=DB::table('academy_branch_classrooms')->where('classroom_id',(int)$t['table_id'])->where('branch_id',(int)$b['branch_id'])->first();if($candidate){$existing=$candidate;break;}}$vals=['branch_id'=>(int)$b['branch_id'],'type_id'=>$typeIds[($bi+$i)%count($typeIds)],'capacity'=>4+(($bi+$i)%17),'is_active'=>1,'status'=>'available','updated_by'=>(int)($b['created_by']?:1),'deleted_at'=>null,'deleted_by'=>null];if($existing){$cid=(int)$existing['classroom_id'];DB::table('academy_branch_classrooms')->where('classroom_id',$cid)->update($vals);}else{$cid=DB::table('academy_branch_classrooms')->insertGetId(['created_by'=>(int)($b['created_by']?:1)]+$vals);$created++;}$this->set('academy_branch_classrooms',$cid,['title'=>$title,'summary'=>'کلاس مجهز با ظرفیت مناسب برای آموزش موسیقی.','description'=>'این کلاس با چیدمان آموزشی، نور مناسب و تجهیزات موردنیاز برای برگزاری دوره‌های حضوری آماده شده است.'],(int)($b['created_by']?:1));if(!DB::table('academy_branch_classroom_assets')->where('classroom_id',$cid)->whereNull('deleted_at')->count()){foreach([['صندلی',4+(($i+$bi)%12)],['پایه نت',2+(($i+$bi)%6)],['سیستم صوتی',1]] as $a){$aid=DB::table('academy_branch_classroom_assets')->insertGetId(['classroom_id'=>$cid,'quantity'=>$a[1],'created_by'=>(int)($b['created_by']?:1),'updated_by'=>(int)($b['created_by']?:1)]);$this->set('academy_branch_classroom_assets',$aid,['title'=>$a[0]],(int)($b['created_by']?:1));$assets++;}}}}return ['created'=>$created,'classrooms'=>DB::table('academy_branch_classrooms')->whereNull('deleted_at')->count(),'assets'=>$assets];});}
}
